const UiFontAa_Glyph *UiMenuFont_Find(uint32_t cp)
{
  uint32_t lo = 0U;
  uint32_t hi = 161U;
  while (lo < hi) {
    uint32_t mid = lo + ((hi - lo) / 2U);
    uint32_t v = ui_menu_glyphs[mid].cp;
    if (v == cp) return &ui_menu_glyphs[mid];
    if (v < cp) lo = mid + 1U;
    else hi = mid;
  }
  return 0;
}

static uint32_t menu_utf8_next(const char **text)
{
  const uint8_t *p = (const uint8_t *)(*text);
  uint32_t cp;
  if (p[0] == 0U) return 0U;
  if (p[0] < 0x80U) { cp = p[0]; p += 1U; }
  else if ((p[0] & 0xE0U) == 0xC0U) {
    cp = ((uint32_t)(p[0] & 0x1FU) << 6) | (uint32_t)(p[1] & 0x3FU); p += 2U;
  } else if ((p[0] & 0xF0U) == 0xE0U) {
    cp = ((uint32_t)(p[0] & 0x0FU) << 12) | ((uint32_t)(p[1] & 0x3FU) << 6) | (uint32_t)(p[2] & 0x3FU); p += 3U;
  } else { cp = (uint32_t)'?'; p += 1U; }
  *text = (const char *)p;
  return cp;
}

uint16_t UiMenuFont_TextWidth(const char *utf8)
{
  uint16_t w = 0U;
  if (utf8 == 0) return 0U;
  while (*utf8) {
    uint32_t cp = menu_utf8_next(&utf8);
    const UiFontAa_Glyph *g;
    if (cp == 0U) break;
    g = UiMenuFont_Find(cp);
    if (g) w = (uint16_t)(w + g->w);
    else w = (uint16_t)(w + (UI_MENU_FONT_H / 3U));
  }
  return w;
}
